function rzPercent(value) {
    const number = Number(value);
    if (!Number.isFinite(number))
        return 0;
    return Math.max(0, Math.min(100, Math.round(number <= 1 ? number * 100 : number)));
}
function endpointReason(lifecycle) {
    if (lifecycle.state === 'degrading')
        return `Quality has fallen ${Math.abs(lifecycle.scoreDelta || 0)} points across retained measurements.`;
    if (lifecycle.state === 'improving')
        return `Quality has improved ${Math.abs(lifecycle.scoreDelta || 0)} points across retained measurements.`;
    if (lifecycle.state === 'stable')
        return `High stability over ${lifecycle.observations} recent measurements.`;
    if (lifecycle.state === 'retired')
        return 'This endpoint has not appeared as the best choice in recent scans.';
    return 'Only one measurement exists; wait for more evidence before acting.';
}
